import{_ as a,c as t,o,ag as i}from"./chunks/framework.DZ_cNctr.js";const n="/docs/screenshots/bif-slide.webp",u=JSON.parse('{"title":"Roche Ventana BIF Viewer","description":"Free online Roche Ventana BIF viewer: open .bif slides from VENTANA DP 200, DP 600 and iScan Coreo scanners in your browser, from your disk or a link, with the overview picture. The overlapping tiles are placed into one slide, as Bio-Formats and OpenSlide place them. A QuPath alternative with nothing to install.","frontmatter":{"title":"Roche Ventana BIF Viewer","description":"Free online Roche Ventana BIF viewer: open .bif slides from VENTANA DP 200, DP 600 and iScan Coreo scanners in your browser, from your disk or a link, with the overview picture. The overlapping tiles are placed into one slide, as Bio-Formats and OpenSlide place them. A QuPath alternative with nothing to install."},"headers":[],"relativePath":"guides/ventana-bif.md","filePath":"guides/ventana-bif.md"}'),r={name:"guides/ventana-bif.md"};function s(l,e,d,h,c,p){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="roche-ventana-bif-viewer" tabindex="-1">Roche Ventana BIF Viewer <a class="header-anchor" href="#roche-ventana-bif-viewer" aria-label="Permalink to &quot;Roche Ventana BIF Viewer&quot;">​</a></h1><p>Open the slides Roche (Ventana) scanners save as <code>.bif</code>: the VENTANA DP 200 and DP 600, and the iScan Coreo and iScan HT before them. No conversion, no upload, no desktop software. The viewer reads only the part you look at.</p><p><img src="'+n+'" alt="Ventana-1.bif open in the viewer: a trichrome-stained liver slide from a VENTANA DP 200, with its overview picture in the panel"></p><h2 id="how-to-open-a-bif-file" tabindex="-1">How to Open a BIF File <a class="header-anchor" href="#how-to-open-a-bif-file" aria-label="Permalink to &quot;How to Open a BIF File&quot;">​</a></h2><ul><li><strong>One file on your disk</strong>, in any browser. Drop it on the viewer, or click <strong>Open Image</strong> and <strong>Choose File</strong>. See <a href="./local-files.html#open-a-file">Local Files</a>.</li><li><strong>A folder of slides</strong>, in Chrome and Edge. One slide opens, several show a list. See <a href="./local-files.html#open-a-folder">Local Files</a>.</li><li><strong>An address</strong>: <code>https://</code>, <code>s3://</code> or <code>gs://</code>. Paste it under <strong>Open Image</strong>. See <a href="./remote-urls.html">Remote URLs</a>.</li><li><strong>Private data</strong>, with a private link or a token. See <a href="./authenticated-sources.html">Private Images and Slides</a>.</li></ul><p>A Ventana slide saved as <code>.tif</code> opens the same way. The viewer recognises it from the file itself.</p><h2 id="what-you-will-see" tabindex="-1">What You Will See <a class="header-anchor" href="#what-you-will-see" aria-label="Permalink to &quot;What You Will See&quot;">​</a></h2><ul><li><strong>The slide, in one piece.</strong> A Ventana scanner takes overlapping tiles and records how they join. The viewer places every tile by those records, at every zoom level, so no strip of tissue shows twice.</li><li><strong>The same picture as other tools.</strong> A DP 200 or DP 600 slide is placed by the rules Roche publishes for the format, and matches Bio-Formats. An iScan slide is placed as OpenSlide places it. OpenSlide is the slide reader inside QuPath and many other tools.</li><li><strong>Several scanned areas</strong> show as one slide. Glass the scanner did not scan shows its background colour.</li><li><strong>Overview picture.</strong> It shows the whole glass, label included, and appears under the title as <strong>Macro</strong>. Click it to enlarge it. A label may show patient details. The viewer shows it and never saves or sends it.</li><li><strong>Colour profile.</strong> A DP 200 or DP 600 slide carries its scanner&#39;s colour profile, and the viewer draws with it. ICC in the RGB settings turns it off. See <a href="./channels.html#icc-colour-profile">Channels</a>.</li><li><strong>Focus planes.</strong> A slide scanned at several focus planes opens at the middle one, with a note.</li><li><strong>Pixel size and magnification.</strong> Both come from the slide, so measurements read in µm and the zoom bar shows the objective. To set your own, see <a href="./calibration.html">Pixel Size and Magnification</a>.</li></ul><p>The viewer was checked on a VENTANA DP 200 slide against Bio-Formats, where every region it read was equal, and on two iScan Coreo slides against OpenSlide.</p><h2 id="if-a-slide-does-not-open" tabindex="-1">If a Slide Does Not Open <a class="header-anchor" href="#if-a-slide-does-not-open" aria-label="Permalink to &quot;If a Slide Does Not Open&quot;">​</a></h2><p>The viewer tells you why.</p><table tabindex="0"><thead><tr><th>What the file has</th><th>What the viewer says</th></tr></thead><tbody><tr><td>Not a Ventana slide</td><td>This .bif file is not a Ventana slide the viewer can read.</td></tr><tr><td>A tile layout from before the scanners Roche documents</td><td>The viewer cannot place the tiles of this slide: it uses an older BIF layout.</td></tr><tr><td>Tile joints the viewer cannot place</td><td>The viewer cannot place the tiles of this slide: it uses a tile joint the scanner did not confirm.</td></tr><tr><td>Another compression</td><td>This BIF file uses a compression the viewer cannot read yet.</td></tr><tr><td>A damaged or incomplete file</td><td>This BIF file looks damaged or incomplete.</td></tr></tbody></table><h2 id="annotations" tabindex="-1">Annotations <a class="header-anchor" href="#annotations" aria-label="Permalink to &quot;Annotations&quot;">​</a></h2><p>Import GeoJSON or OME-XML files, and export them, from the <strong>Annotations</strong> panel. Send a link that opens the slide with its annotations. <a href="./annotation-exchange.html">Exchanging Annotations</a> shows how. To draw, measure and label shapes on the slide, see <a href="./annotations.html">Annotations</a>.</p><h2 id="public-slides-to-try" tabindex="-1">Public Slides to Try <a class="header-anchor" href="#public-slides-to-try" aria-label="Permalink to &quot;Public Slides to Try&quot;">​</a></h2><p><a href="https://openslide.org" target="_blank" rel="noreferrer">OpenSlide</a> shares test slides in its <a href="https://openslide.cs.cmu.edu/download/openslide-testdata/Ventana/" target="_blank" rel="noreferrer">Ventana folder</a>. <code>Ventana-1.bif</code> is a DP 200 slide under CC0. Download it, then drop it on the viewer.</p><h2 id="for-your-it-team" tabindex="-1">For Your IT Team <a class="header-anchor" href="#for-your-it-team" aria-label="Permalink to &quot;For Your IT Team&quot;">​</a></h2><p>To open a slide by address, the server must answer byte-range requests and allow them through <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS" target="_blank" rel="noreferrer">CORS</a>. For a bucket, allow <code>GET</code> and the <code>Range</code> header in its CORS rules. <a href="./remote-urls.html#what-the-server-needs">What the Server Needs</a> has the details.</p><p>When a server cannot send parts of a file, the viewer says so. Download the slide and open it from your computer.</p><p>Addresses that start with <code>s3://</code> and <code>gs://</code> work too.</p><h2 id="image-credits" tabindex="-1">Image credits <a class="header-anchor" href="#image-credits" aria-label="Permalink to &quot;Image credits&quot;">​</a></h2><p>The screenshot uses <code>Ventana-1.bif</code> from the OpenSlide test data, credit PathAI, CC0. See <a href="./../sample-data.html">Sample Data and Credits</a>.</p><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h2><p>The slide is read in your browser. Opening one counts as one opened image of the kind &quot;Roche Ventana BIF file&quot;. The file name and address are never recorded. See the <a href="https://find-nuclei.github.io/privacy.html" target="_blank" rel="noreferrer">privacy policy</a>.</p><p><small>Product names are trademarks of their owners. Find Nuclei is not affiliated with them.</small></p>',25)])])}const m=a(r,[["render",s]]);export{u as __pageData,m as default};
